insert into public.business_settings (id) values (1) on conflict (id) do nothing;
insert into public.services (slug, category, name, tagline, description, price_min_cents, price_max_cents, price_notes, billing_type, purchase_mode, deposit_percent, deliverables, exclusions, revisions_included, timeline_text, is_featured, sort_order) values
  ('starter-website', 'website', 'Starter Website', 'A fast, professional site to get your business found online.', 'Perfect for new businesses, freelancers and local services that need a credible web presence quickly. Built mobile-first on a modern stack, with a design customised to your brand.', 79900, 149900, 'Base price covers up to 5 pages in English. Extra pages, bilingual (BM/EN) content or copywriting move the price towards the top of the range and are confirmed in writing before work starts.', 'one_time', 'direct', 50, '["Up to 5 pages (e.g. Home, About, Services, Gallery, Contact) at the base price","Mobile-first responsive design customised to your logo and colours","Contact form with email notification and WhatsApp click-to-chat button","Basic on-page SEO: page titles, meta descriptions, sitemap and Google Search Console submission","Google Maps embed and social media links","Free SSL and deployment to a free-tier host (Vercel/Netlify) or your existing hosting","30 days of post-launch bug fixes"]'::jsonb, '["Domain name and paid hosting fees (we can register them for you at cost)","Copywriting beyond light editing of the text you provide","Logo or brand identity design","Online payments, bookings or e-commerce features","Paid stock photos or premium plugin licences","Ongoing content updates after the 30-day support window (see Maintenance plans)"]'::jsonb, 2, '7–14 working days after we receive your content', true, 10),
  ('business-website', 'website', 'Business Website', 'A custom-designed site that turns visitors into enquiries.', 'For established SMEs that need a distinctive design, content they can edit themselves, and proper tracking of where their leads come from.', 150000, 399900, null, 'one_time', 'quote', 50, '["Up to 12 pages with a custom design (mock-up approved before build)","Content management so your team can edit pages, news or blog posts","Lead capture forms with email notifications and spam protection","Google Analytics 4 and Search Console setup","On-page SEO, structured data (schema) and performance optimisation for Core Web Vitals","WhatsApp / live chat integration","Optional bilingual (BM/EN) structure","1-hour handover training and 30 days of post-launch bug fixes"]'::jsonb, '["Copywriting, photography and video production (available as quoted add-ons)","Paid theme, plugin or third-party software licences","E-commerce and online payment features","Domain, hosting and email hosting fees","Guaranteed search rankings — no honest agency can promise these"]'::jsonb, 3, '3–5 weeks depending on scope', true, 20),
  ('ecommerce-website', 'website', 'E-commerce Website', 'Sell online with secure local payments and simple order management.', 'An online store on Shopify, WooCommerce or a custom Next.js build — chosen to fit your budget, catalogue size and how you want to manage orders.', 300000, 799900, null, 'one_time', 'quote', 50, '["Store setup with up to 50 products loaded from your spreadsheet (more as a quoted add-on)","Payment gateway integration (cards, FPX and e-wallets supported by your chosen gateway) using your own merchant account","Shipping zones and rates, discount codes and tax settings","Order notification emails and basic inventory tracking","Mobile-optimised product, cart and checkout pages","On-page SEO for product and category pages","1-hour training session plus a recorded video walkthrough"]'::jsonb, '["Payment gateway fees, merchant account approval and platform subscriptions (e.g. Shopify plan) — billed to you directly by the provider","Product photography and product descriptions","Marketplace integrations (Shopee, Lazada, TikTok Shop) unless quoted","Custom ERP / accounting integrations unless quoted"]'::jsonb, 3, '4–8 weeks depending on scope', false, 30),
  ('custom-web-application', 'website', 'Custom Web Application', 'Portals, dashboards and internal tools built around your workflow.', 'Booking systems, client portals, internal dashboards and SaaS MVPs. Scoped in a paid or free discovery session and delivered in milestones you approve.', null, null, null, 'one_time', 'quote', 30, '["Discovery session and written requirements specification","UI/UX wireframes for key screens","Full-stack build (e.g. Next.js, TypeScript, PostgreSQL/Supabase) with user accounts and roles","Admin dashboard and third-party API integrations as scoped","Automated tests for critical flows, deployment and documentation","Milestone-based delivery and payments"]'::jsonb, '["Features not listed in the signed proposal (change requests are quoted separately)","Third-party service, API and hosting fees","Ongoing support after the warranty period (see Maintenance plans)"]'::jsonb, 2, 'Typically 6–16 weeks, confirmed in the proposal', false, 40),
  ('ai-chatbot-integration', 'ai', 'AI Chatbot Integration', 'A 24/7 website assistant that answers FAQs and captures leads.', 'An AI chatbot trained on your business information that answers common questions, collects enquiries and hands over to you on WhatsApp when a human is needed.', 49900, null, null, 'one_time', 'quote', 50, '["Chatbot set up on one website, trained on your FAQ, services and policies (up to ~20 pages of content at the base price)","Lead capture (name, phone, email) delivered to your email or Google Sheet","Hand-over link to WhatsApp or your contact form","Guardrails so the bot does not invent prices, promises or policies","Two rounds of answer tuning in the first 14 days"]'::jsonb, '["AI model usage fees from the AI provider (usually low; billed to your own account)","WhatsApp Business Platform (API) integration and Meta conversation fees","CRM integrations and languages beyond English and Bahasa Malaysia unless quoted"]'::jsonb, 2, '5–10 working days', true, 50),
  ('ai-workflow-automation', 'ai', 'AI Workflow Automation', 'Stop copy-pasting. Automate the repetitive work between your apps.', 'We map one or two of your repetitive processes and automate them — for example enquiries to CRM to follow-up messages, invoice reminders, report generation or document summarisation.', 99900, null, null, 'one_time', 'quote', 50, '["Process mapping session and written automation plan","1–2 automated workflows using n8n, Make, Zapier or custom code","AI steps (classification, summarisation, drafting) with human approval where decisions matter","Error alerts and a simple run log","Documentation and a handover call"]'::jsonb, '["Subscription fees for automation platforms and APIs (billed to your account)","Systems without an API or export option","Automating decisions that legally require human sign-off"]'::jsonb, 2, '1–3 weeks', false, 60),
  ('ai-customer-support-system', 'ai', 'AI Customer Support System', 'Answer customers instantly across channels — with humans in control.', 'A knowledge-based support assistant for your website and messaging channels, with escalation to your team, conversation history and insight into what customers ask most.', 149900, null, null, 'one_time', 'quote', 50, '["Knowledge base built from your documents, FAQs and policies","Website support assistant plus one messaging channel via official APIs where available","Escalation rules and human hand-over","Conversation logs and a monthly report of top questions","Staff training session"]'::jsonb, '["Meta/WhatsApp Business Platform fees and AI model usage fees","Helpdesk or CRM software licences","24/7 human support staffing"]'::jsonb, 3, '2–4 weeks', false, 70),
  ('custom-ai-agent', 'ai', 'Custom AI Agent Development', 'AI agents that do real work — with approvals where it matters.', 'Purpose-built AI agents that research, draft, triage or operate tools on your behalf, designed with permissions, audit logs and human approval for sensitive actions.', null, null, null, 'one_time', 'quote', 30, '["Discovery workshop and agent design document","Tool and API integrations with least-privilege access","Human-in-the-loop approval steps and audit logging","Evaluation tests to measure quality before go-live","Deployment, monitoring and handover"]'::jsonb, '["AI model usage and third-party API fees","Actions the agent should not take without human approval (we design these out)","Work outside the signed proposal"]'::jsonb, 2, 'Confirmed in the proposal', false, 80),
  ('basic-maintenance', 'maintenance', 'Basic Website Maintenance', 'Keep your site secure, backed up and online.', 'Essential care for small websites. Cancel anytime — your plan stays active until the end of the paid month.', 9900, null, null, 'monthly', 'direct', 100, '["Monthly software, plugin and security updates","Uptime monitoring with alerts","Monthly backup","Up to 30 minutes of small content edits per month (does not roll over)","Email support with a 2-business-day response target"]'::jsonb, '["New pages, features or redesigns (quoted separately)","Domain and hosting fees unless separately agreed","Fixing issues caused by third-party changes beyond the included time"]'::jsonb, 0, 'Monthly, cancel anytime', false, 90),
  ('business-maintenance', 'maintenance', 'Business Maintenance', 'Proactive care plus monthly improvements.', 'For businesses whose website generates leads. Includes regular edits and a monthly health report.', 24900, null, null, 'monthly', 'direct', 100, '["Everything in Basic Website Maintenance","Weekly backups","Up to 2 hours of content or design edits per month (does not roll over)","Monthly performance, SEO health and analytics summary","Minor bug fixes","Priority email/WhatsApp support with a 1-business-day response target"]'::jsonb, '["New features or major redesigns (quoted separately)","Paid advertising management","Third-party licence and hosting fees"]'::jsonb, 0, 'Monthly, cancel anytime', true, 100),
  ('premium-maintenance', 'maintenance', 'Premium Maintenance & Support', 'Your on-call web and AI team, every month.', 'For businesses that rely on their website, chatbot or automations every day and want ongoing development time.', 49900, null, null, 'monthly', 'direct', 100, '["Everything in Business Maintenance","Up to 5 hours of development, edits or automation tweaks per month (does not roll over)","Daily backups where your hosting supports them","AI chatbot / automation content updates for systems we built","Quarterly 30-minute strategy call","Same-business-day response target for critical issues (Mon–Fri, 9am–6pm MYT)"]'::jsonb, '["Work beyond the included hours (billed at an agreed hourly rate)","Third-party licence, AI usage and hosting fees","24/7 on-call support"]'::jsonb, 0, 'Monthly, cancel anytime', false, 110)
